insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('a', 'The Adjectives Mastery', 'בשיעור זה נהפוך למאסטרים של Adjectives - שמות תואר! נלמד על עוד שמות תואר חדשים, על היפוך הסדר כאשר מתארים דברים בתוך משפט, ועל שמות תואר כמילות השוואה (BiggER, SmallER ועוד)!', 'teacher_maya', 'draft', 2, 50, 'questlines\a\_index.yaml', '{"catalog_set":null,"quest_count":4,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('adjectives_basics', 'Adjectives - מילות תיאור', 'A painter whose kingdom painting lost all its describing words: learn what an adjective is, basic colors, sizes and feelings, and how to place an adjective before a noun.', 'Painter', 'draft', 1, 50, 'questlines\adjectives_basics\_index.yaml', '{"catalog_set":null,"quest_count":6,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('adjectives_basics_homework', 'Adjectives - שיעורי בית', 'Homework for the Adjectives line: no new words. The Painter paints a gift for the girl from the park only from the learner''s describing words, and the learner shows without help that they still know colors, sizes and feelings, the adjective before the noun, and the adjective after is / are.', 'Painter', 'draft', 1, 50, 'questlines\adjectives_basics_homework\_index.yaml', '{"catalog_set":null,"quest_count":1,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('adjectives_mastery_homework', 'The Adjectives Mastery - שיעורי בית', 'Homework for The Adjectives Mastery line: no new rule. The lesson ended with Maya running off to study because the learners became masters before her. She comes back after a night of studying and wants to check her own answer cards against cards the masters write alone: the adjective before the noun, and comparisons with -er and than.', 'teacher_maya', 'draft', 1, 50, 'questlines\adjectives_mastery_homework\_index.yaml', '{"catalog_set":null,"quest_count":1,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('articles_a_an', 'A / An - a או an', 'Nemo the Netless guards two tiny twin fish named A and AN for the Sea Queen: learn that a means one thing, that an comes before a vowel letter (a, e, i, o, u), and that the very next word decides which one to use.', 'Fisherman', 'draft', 1, 50, 'questlines\articles_a_an\_index.yaml', '{"catalog_set":null,"quest_count":6,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
