insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('do_does_homework', 'The DO / DOES Secret - שיעורי בית', 'Homework for the DO / DOES Secret line: no new rule. The four speaking stones work again and tomorrow is market day, so Tomlin, the gate guard whose stone was the last one saved, checks that the learner can stand at the gate as a guard for a day: choosing do or does alone in questions and in not sentences, with no -s on the verb after does.', 'Main Gate Gaurd 1', 'draft', 1, 50, 'questlines\do_does_homework\_index.yaml', '{"catalog_set":null,"quest_count":1,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
