insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('noun_repair_shop_homework', 'Noun Repair Shop: The Missing Names - שיעורי בית', 'Homework for the Noun Repair Shop line: no new words. Since the shop reopened, broken name tags keep arriving from all over the kingdom, and Maya asks the learner to fix today''s box alone - telling nouns from other words, completing and spelling them, and using them in short sentences.', 'teacher_maya', 'draft', 1, 50, 'questlines\noun_repair_shop_homework\_index.yaml', '{"catalog_set":null,"quest_count":1,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
