insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('personal_pronouns', 'Personal Pronouns - כינויי גוף', 'The Village Play: the boy wrote every name again and again until the notebook ran out, so the troupe learns the short words that stand in for a name - I, You, He, She, It, We, They.', 'Village Head', 'draft', 1, 50, 'questlines\personal_pronouns\_index.yaml', '{"catalog_set":null,"quest_count":5,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
