insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('the_kingdoms_worst_day', 'The Kingdom’s Worst Day - שיעור תרגול verbs nouns adjectivs', 'Practice nouns, verbs, adjectives, sentence building, and speaking with clear Hebrew guidance and essential English.', 'teacher_maya', 'draft', 1, 50, 'questlines\the_kingdoms_worst_day\_index.yaml', '{"catalog_set":null,"quest_count":4,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('the_kingdoms_worst_day_homework', 'The Kingdom''s Worst Day - שיעורי בית', 'Homework for The Kingdom''s Worst Day line: no new words. On the evening after the fair, the wind mixes up the word cards on the fair''s board by the gate. Fenn the guard asks the learner to pick out the verbs, put nouns, verbs and adjectives in their places, and rebuild short sentences alone before the gate closes for the night.', 'City Gaurd Info', 'draft', 1, 50, 'questlines\the_kingdoms_worst_day_homework\_index.yaml', '{"catalog_set":null,"quest_count":1,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
