insert into public.questlines (key, display_name, theme, default_giver_external_id, status, level_min, level_max, source_path, source_metadata) values ('wh_questions_homework', 'Wh-Questions - שיעורי בית', 'Homework for the Wh-Questions line: no new words. The ghost writes a question notebook so she never forgets again, and the learner fills it with What, Where, When, Who, Why and How questions without help.', 'Ghost', 'draft', 1, 50, 'questlines\wh_questions_homework\_index.yaml', '{"catalog_set":null,"quest_count":1,"source_note":null,"source_status":null}'::jsonb) on conflict (key) do update set display_name = excluded.display_name, theme = excluded.theme, default_giver_external_id = excluded.default_giver_external_id, status = excluded.status, level_min = excluded.level_min, level_max = excluded.level_max, source_path = excluded.source_path, source_metadata = excluded.source_metadata, updated_at = now();
